<?php
declare(strict_types=1);
namespace KodVadAll\Modules\HR;
use PDO;
use RuntimeException;
use Throwable;

final class HRController
{
 public static function handle(PDO $db,array $admin):void
 {
  kd_require_permission('employees.view');$action=(string)($_GET['action']??'list');$id=max(0,(int)($_GET['id']??0));$errors=[];
  if($_SERVER['REQUEST_METHOD']==='POST'){
   kd_csrf_check();kd_require_permission('employees.manage');
   try{
    $form=(string)($_POST['form_action']??'');
    if($form==='save'){
     $employeeId=(int)($_POST['employee_id']??0);$first=trim((string)($_POST['first_name']??''));$last=trim((string)($_POST['last_name']??''));$email=trim((string)($_POST['email']??''));$department=trim((string)($_POST['department']??''));$salary=(float)($_POST['base_salary']??0);$currency=strtoupper((string)($_POST['currency']??'TRY'));$hire=trim((string)($_POST['hire_date']??''));
     if($first===''||$last===''||mb_strlen($first)>100||mb_strlen($last)>100)throw new RuntimeException('Ad ve soyad zorunludur.');
     if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('E-posta adresi geçersiz.');
     if($salary<0||!in_array($currency,['TRY','USD','EUR','GBP'],true))throw new RuntimeException('Maaş veya para birimi geçersiz.');
     if($hire!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$hire))throw new RuntimeException('İşe giriş tarihi geçersiz.');
     $departmentId=null;if($department!==''){$db->prepare("INSERT IGNORE INTO departments (name,status,created_at) VALUES (?,'active',NOW())")->execute([$department]);$q=$db->prepare('SELECT id FROM departments WHERE name=?');$q->execute([$department]);$departmentId=(int)$q->fetchColumn();}
     $status=in_array($_POST['employment_status']??'', ['active','inactive','terminated'],true)?$_POST['employment_status']:'active';$data=[$first,$last,$email?:null,trim((string)($_POST['phone']??''))?:null,$departmentId,trim((string)($_POST['position']??''))?:null,$hire?:null,$status,$salary,$currency,trim((string)($_POST['notes']??''))?:null];
     if($employeeId>0){$db->prepare('UPDATE employees SET first_name=?,last_name=?,email=?,phone=?,department_id=?,position=?,hire_date=?,employment_status=?,base_salary=?,currency=?,notes=?,updated_at=NOW() WHERE id=?')->execute([...$data,$employeeId]);kd_audit('employee.updated','employee',$employeeId);}
     else{$tmp='TMP-'.bin2hex(random_bytes(8));$db->prepare('INSERT INTO employees (employee_code,first_name,last_name,email,phone,department_id,position,hire_date,employment_status,base_salary,currency,notes,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,NOW())')->execute([$tmp,...$data]);$employeeId=(int)$db->lastInsertId();$code='PRS-'.date('Y').'-'.str_pad((string)$employeeId,5,'0',STR_PAD_LEFT);$db->prepare('UPDATE employees SET employee_code=? WHERE id=?')->execute([$code,$employeeId]);kd_audit('employee.created','employee',$employeeId);}
     self::go('view',$employeeId);
    }
    if($form==='leave'){
     $employeeId=(int)($_POST['employee_id']??0);$type=trim((string)($_POST['leave_type']??'annual'));$start=(string)($_POST['start_date']??'');$end=(string)($_POST['end_date']??'');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$end)||$end<$start)throw new RuntimeException('İzin tarih aralığını kontrol edin.');$days=(new \DateTimeImmutable($start))->diff(new \DateTimeImmutable($end))->days+1;$q=$db->prepare("SELECT id FROM employees WHERE id=? AND employment_status='active'");$q->execute([$employeeId]);if(!$q->fetchColumn())throw new RuntimeException('Aktif personel seçin.');$db->prepare("INSERT INTO employee_leaves (employee_id,leave_type,start_date,end_date,day_count,status,reason,created_by,created_at) VALUES (?,?,?,?,?,'pending',?,?,NOW())")->execute([$employeeId,$type,$start,$end,$days,trim((string)($_POST['reason']??''))?:null,(int)$admin['id']]);kd_audit('employee.leave_requested','employee',$employeeId);\KodVadAll\Core\NotificationService::notifyRoles($db,['owner','admin','manager'],'Yeni izin talebi','Personel izin talebi oluşturdu.','index.php?page=employees&action=view&id='.$employeeId,'info');self::go('view',$employeeId);
    }
    if($form==='leave_status'){
     $leaveId=(int)($_POST['leave_id']??0);$status=(string)($_POST['status']??'');if(!in_array($status,['approved','rejected'],true))throw new RuntimeException('İzin kararı geçersiz.');$q=$db->prepare("UPDATE employee_leaves SET status=?,reviewed_by=?,updated_at=NOW() WHERE id=? AND status='pending'");$q->execute([$status,(int)$admin['id'],$leaveId]);if(!$q->rowCount())throw new RuntimeException('Bekleyen izin talebi bulunamadı.');$employeeId=(int)($_POST['employee_id']??0);kd_audit('employee.leave_'.$status,'employee',$employeeId);self::go('view',$employeeId);
    }
    if($form==='attendance'){
     $employeeId=(int)($_POST['employee_id']??0);$date=(string)($_POST['work_date']??date('Y-m-d'));$in=trim((string)($_POST['check_in']??''));$out=trim((string)($_POST['check_out']??''));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Çalışma tarihi geçersiz.');$inSql=$in!==''?str_replace('T',' ',$in).(strlen($in)===16?':00':''):null;$outSql=$out!==''?str_replace('T',' ',$out).(strlen($out)===16?':00':''):null;if($inSql&&$outSql&&$outSql<$inSql)throw new RuntimeException('Çıkış saati giriş saatinden önce olamaz.');$db->prepare('INSERT INTO employee_attendance (employee_id,work_date,check_in,check_out,notes,created_by,created_at) VALUES (?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE check_in=VALUES(check_in),check_out=VALUES(check_out),notes=VALUES(notes),updated_at=NOW()')->execute([$employeeId,$date,$inSql,$outSql,trim((string)($_POST['attendance_notes']??''))?:null,(int)$admin['id']]);kd_audit('employee.attendance_saved','employee',$employeeId);self::go('view',$employeeId);
    }
    if($form==='payment'){
     $employeeId=(int)($_POST['employee_id']??0);$accountId=(int)($_POST['account_id']??0);$type=(string)($_POST['payment_type']??'salary');$amount=(float)($_POST['amount']??0);$period=trim((string)($_POST['pay_period']??''));$date=(string)($_POST['payment_date']??date('Y-m-d'));if(!in_array($type,['salary','advance','bonus','commission'],true)||$amount<=0||!preg_match('/^\d{4}-\d{2}$/',$period)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Ödeme türü, tutar veya dönem geçersiz.');$q=$db->prepare('SELECT * FROM employees WHERE id=? AND employment_status=?');$q->execute([$employeeId,'active']);$employee=$q->fetch();if(!$employee)throw new RuntimeException('Aktif personel bulunamadı.');$q=$db->prepare("SELECT id,currency FROM financial_accounts WHERE id=? AND status='active'");$q->execute([$accountId]);$account=$q->fetch();if(!$account||$account['currency']!==$employee['currency'])throw new RuntimeException('Personel ile aynı para biriminde aktif hesap seçin.');if($type==='salary'){$q=$db->prepare("SELECT COUNT(*) FROM employee_payments WHERE employee_id=? AND payment_type='salary' AND pay_period=?");$q->execute([$employeeId,$period]);if((int)$q->fetchColumn()>0)throw new RuntimeException('Bu dönem için maaş ödemesi zaten kaydedilmiş.');}
     $db->beginTransaction();$db->prepare("INSERT INTO financial_transactions (account_id,transaction_type,direction,amount,currency,transaction_date,party_type,party_id,category,reference_no,description,created_by,created_at) VALUES (?,'expense','debit',?,?,?,'employee',?,?,?,?,?,NOW())")->execute([$accountId,$amount,$employee['currency'],$date,$employeeId,'Personel '.$type,$period,'Personel '.$type.' ödemesi',(int)$admin['id']]);$db->prepare('INSERT INTO employee_payments (employee_id,account_id,payment_type,pay_period,amount,currency,payment_date,reference_no,notes,created_by,created_at) VALUES (?,?,?,?,?,?,?,?,?,?,NOW())')->execute([$employeeId,$accountId,$type,$period,$amount,$employee['currency'],$date,trim((string)($_POST['reference_no']??''))?:null,trim((string)($_POST['payment_notes']??''))?:null,(int)$admin['id']]);$db->commit();kd_audit('employee.payment_recorded','employee',$employeeId);self::go('view',$employeeId);
    }
   }catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('KodVadAll HR: '.$e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Personel işlemi tamamlanamadı.';$action=(string)($_GET['action']??'list');$id=max(0,(int)($_GET['id']??0));}
  }
  if($action==='create'||$action==='edit'){$employee=['id'=>0,'first_name'=>'','last_name'=>'','email'=>'','phone'=>'','department_name'=>'','position'=>'','hire_date'=>'','employment_status'=>'active','base_salary'=>'0.00','currency'=>'TRY','notes'=>''];if($action==='edit'){$q=$db->prepare('SELECT e.*,d.name department_name FROM employees e LEFT JOIN departments d ON d.id=e.department_id WHERE e.id=?');$q->execute([$id]);$employee=$q->fetch()?:null;if(!$employee)self::notFound();}$pageTitle=$action==='create'?'Yeni personel':'Personel bilgilerini düzenle';ob_start();require KD_ROOT.'/app/Views/hr/form.php';$content=ob_get_clean();require KD_ROOT.'/app/Views/layouts/admin.php';return;}
  if($action==='view'){$q=$db->prepare('SELECT e.*,d.name department_name FROM employees e LEFT JOIN departments d ON d.id=e.department_id WHERE e.id=?');$q->execute([$id]);$employee=$q->fetch();if(!$employee)self::notFound();$q=$db->prepare('SELECT * FROM employee_leaves WHERE employee_id=? ORDER BY id DESC LIMIT 30');$q->execute([$id]);$leaves=$q->fetchAll();$q=$db->prepare('SELECT * FROM employee_attendance WHERE employee_id=? ORDER BY work_date DESC LIMIT 30');$q->execute([$id]);$attendance=$q->fetchAll();$q=$db->prepare('SELECT p.*,a.name account_name FROM employee_payments p JOIN financial_accounts a ON a.id=p.account_id WHERE p.employee_id=? ORDER BY p.id DESC LIMIT 30');$q->execute([$id]);$payments=$q->fetchAll();$accounts=$db->prepare("SELECT id,name,currency FROM financial_accounts WHERE status='active' AND currency=? ORDER BY name");$accounts->execute([$employee['currency']]);$paymentAccounts=$accounts->fetchAll();$pageTitle=$employee['first_name'].' '.$employee['last_name'];ob_start();require KD_ROOT.'/app/Views/hr/detail.php';$content=ob_get_clean();require KD_ROOT.'/app/Views/layouts/admin.php';return;}
  $q=trim((string)($_GET['q']??''));$status=in_array($_GET['status']??'', ['active','inactive','terminated'],true)?$_GET['status']:'';$where=[];$params=[];if($q!==''){$where[]='(e.first_name LIKE ? OR e.last_name LIKE ? OR e.employee_code LIKE ? OR e.email LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like,$like);}if($status!==''){$where[]='e.employment_status=?';$params[]=$status;}$sql=$where?' WHERE '.implode(' AND ',$where):'';$q=$db->prepare('SELECT e.*,d.name department_name FROM employees e LEFT JOIN departments d ON d.id=e.department_id'.$sql.' ORDER BY e.id DESC LIMIT 150');$q->execute($params);$employees=$q->fetchAll();$pageTitle='Personel & İnsan Kaynakları';ob_start();require KD_ROOT.'/app/Views/hr/list.php';$content=ob_get_clean();require KD_ROOT.'/app/Views/layouts/admin.php';
 }
 private static function go(string $action='list',int $id=0):never{$u='index.php?page=employees';if($action!=='list')$u.='&action='.$action;if($id)$u.='&id='.$id;header('Location: '.$u,true,303);exit;}
 private static function notFound():never{http_response_code(404);exit('Personel kaydı bulunamadı.');}
}
